            if (原本全屏) {
                let 看见窗口 = false;
                let 次数 = 0;
                const 轮询 = window.setInterval(() => {
                    次数++;
                    const 有窗口 = Boolean(弹窗文档.querySelector('dialog[open], [role="dialog"], .popup[open]'));
                    看见窗口 ||= 有窗口;
