/**
 * 经济系统(P3:压力成型)——纪律:货币只走脚本结算,AI 不碰钱(变量分工表)。
 *
 * 结算入口:经济结算(世界时间推进后调用,期号去重防重复入账)。时间只读绝对时段；
 * 软计数(拾取/偷窃冷却)存 chat 变量 `_经济`,回档丢了也无害,且带未来时段作废守卫。
 */

// ── 软计数(chat 变量) ──

interface 经济计数 {
  拾取: Record<string, boolean>; // `${房间}:${period}` → 已拾取
  偷窃上次: Record<string, number>; // 门牌 → 上次翻找绝对时段(冷却)
}

function 读计数(): 经济计数 {
  const v = (_.get(getVariables({ type: 'chat' }), '_经济') ?? {}) as Partial<经济计数>;
  return { 拾取: v.拾取 ?? {}, 偷窃上次: v.偷窃上次 ?? {} };
}

function 写计数(c: 经济计数): void {
  void Promise.resolve(insertOrAssignVariables({ _经济: c }, { type: 'chat' })).catch((e: unknown) =>
    console.error('[人妻公寓·经济] 计数写入失败', e),
  );
}

export interface 经济结果 {
  提示: string;
  事件?: string;
  变动?: boolean;
}

function 按百元取整(金额: number): number {
  return Math.max(0, Math.round(金额 / 100) * 100);
}

function 上交不足扣分(完成率: number): number {
  if (完成率 >= 1) return 0;
  if (完成率 >= 0.8) return 2;
  if (完成率 >= 0.5) return 5;
  if (完成率 > 0) return 8;
  return 12;
}

function 胜任态度(胜任度: number, 红线: number, 通牒: boolean): string {
  if (通牒 || 胜任度 <= 红线) return '通牒';
  const 距离 = 胜任度 - 红线;
  return 距离 >= 30 ? '满意' : 距离 >= 20 ? '平淡' : 距离 >= 10 ? '不满' : '危险';
}

function 未结楼务报表(data: SchemaType, 当前绝对时段: number): string[] {
  const 级别序 = { 紧急: 3, 重要: 2, 日常: 1 } as const;
  const 排序 = [...data.系统._管理考核.活跃任务].sort((a, b) => {
    const a逾 = 当前绝对时段 > a.截止时段 ? 1 : 0;
    const b逾 = 当前绝对时段 > b.截止时段 ? 1 : 0;
    return b逾 - a逾 || 级别序[b.级别] - 级别序[a.级别] || a.截止时段 - b.截止时段;
  });
  const 展开 = 排序.slice(0, 3).map(任务 => {
    const 时差 = 当前绝对时段 - 任务.截止时段;
    return `${管理任务摘要(任务)}${时差 > 0 ? `已逾期${时差}时段` : `尚余${Math.max(0, -时差)}时段`}`;
  });
  if (排序.length > 3) 展开.push(`其余未结楼务${排序.length - 3}件`);
  return 展开;
}

/** 只在没有更高优先级未结责任时，把本期按期完成的重要事项编入父亲报表。 */
function 按期完成楼务报表(data: SchemaType, 期界时段: number, 有其他高优先问题: boolean): string[] {
  const 管理 = data.系统._管理考核;
  const 有高优先未结 = 管理.活跃任务.some(
    任务 => 期界时段 > 任务.截止时段 || 任务.级别 === '重要' || 任务.级别 === '紧急',
  );
  if (有其他高优先问题 || 有高优先未结) return [];
  return 管理.本期完成摘要
    .filter(项 => 项.按期 && (项.级别 === '重要' || 项.级别 === '紧急'))
    .map(项 => `本期按期完成重要楼务：${项.地点}${项.任务}（${项.级别}，${项.方式}）`);
}

function 逾期楼务原因(data: SchemaType, 任务ids: readonly string[], 当前时段: number, 允许旧逾期 = false): string {
  const ids = new Set(任务ids);
  const 新逾期 = data.系统._管理考核.活跃任务.find(任务 => ids.has(任务.id));
  if (新逾期) return 管理任务摘要(新逾期);
  if (!允许旧逾期) return '';
  const 旧逾期 = data.系统._管理考核.活跃任务.find(任务 => 任务.逾期已扣 && 当前时段 > 任务.截止时段);
  return 旧逾期 ? 管理任务摘要(旧逾期) : '';
}

function 合并父亲报表(旧报表: string, 新报表: string): string {
  if (!旧报表) return 新报表;
  if (!新报表 || 旧报表.includes(新报表)) return 旧报表;
  return `${旧报表};${新报表}`;
}

function 风闻通牒原因(
  data: SchemaType,
  责任: readonly { 事件ID: string; 摘要: string; 扣分: number }[],
  延续紧急危机: boolean,
): string {
  const 有本期风闻扣分 = 责任.some(item => item.扣分 > 0);
  if (!有本期风闻扣分 && !延续紧急危机) return '';
  const 责任事件 = new Set(责任.filter(item => item.扣分 > 0).map(item => item.事件ID));
  const 候选事件 = data.系统._风闻账.最近事件.filter(
    event => 责任事件.has(event.id) || (延续紧急危机 && event.状态 === '活跃' && event.胜任责任 > 0),
  );
  const 母亲硬事件 = 候选事件.find(
    event =>
      event.门牌 === '302' &&
      (event.迹象 === '硬证据' || event.迹象 === '正式投诉' || event.胜任责任 >= 6),
  );
  if (母亲硬事件) return `母亲事发：${风闻事件安全摘要(母亲硬事件)}`;
  const 摘要 = 候选事件[0] ? 风闻事件安全摘要(候选事件[0]) : 责任.find(item => item.扣分 > 0)?.摘要;
  return `公开丑闻${摘要 ? `：${摘要}` : '：楼内风闻危机已经传到父亲那里'}`;
}

function 风闻责任类别(data: SchemaType, 事件ID: string): 胜任责任类别 {
  const event = data.系统._风闻账.最近事件.find(item => item.id === 事件ID);
  return event?.门牌 === '302' &&
    (event.迹象 === '硬证据' || event.迹象 === '正式投诉' || event.胜任责任 >= 6)
    ? '母亲事发'
    : '公开丑闻';
}

function 坏结局文本(类别: 胜任责任类别, 原因: string): string {
  switch (类别) {
    case '账目亏空':
      return '考验失败·欠租烂账:父亲提前回国,账本摊在桌上,一页一页翻得很慢。"这楼是做慈善吗?"他没等你解释,钥匙已经收走了';
    case '母亲事发':
      return `考验失败·母亲事发:父亲提前回国，把${原因}的材料放在桌上。他没有接受解释，只收走了管理员钥匙`;
    case '公开丑闻':
      return `考验失败·公开丑闻:父亲提前回国，把${原因}的投诉记录摊在桌上。他没有接受解释，只收走了管理员钥匙`;
    case '失联抗命':
      return `考验失败·失联抗命:父亲提前回国，把${原因}的通话记录放在桌上。他没再问理由，只收走了管理员钥匙`;
    case '楼务失职':
    case '综合失职':
      return `考验失败·楼务失职:父亲提前回国，把${原因}的记录压在值班桌上。他没再听解释，只收走了管理员钥匙`;
  }
}

function 主因说明(类别: 胜任责任类别, 原因: string): string {
  if (!原因 || 原因.startsWith(类别)) return 原因 || 类别;
  return `${类别}：${原因}`;
}

/** 只用于读取尚未带结构化主因的旧存档；新结算一律依赖记分条目。 */
function 旧通牒类别(原因: string): 胜任责任类别 {
  if (/母亲|302/.test(原因)) return '母亲事发';
  if (/风闻|投诉|丑闻|证据/.test(原因)) return '公开丑闻';
  if (/未接|失联|电话/.test(原因)) return '失联抗命';
  if (/欠租|租金|上交|账/.test(原因)) return '账目亏空';
  if (/楼务|任务|逾期|报修|清洁|投诉处理/.test(原因)) return '楼务失职';
  return '综合失职';
}

// ============================================
// 收租日 + 上交日 + 父亲来电 + 最后通牒(每 AI 楼结算一次,期号去重)
// ============================================

/**
 * 经济结算:收租(每户,入住楼错开相位)→ 上交日(全局期:扣上交/胜任度记分/未接覆盖/通牒判定/
 * 生成待接来电)。返回 toast 短句列表(调用方转发 提示 事件)。
 */
export function 经济结算(data: SchemaType, _消息楼层?: number): string[] {
  if (data.系统._坏结局) return [];
  const 当前绝对时段 = 取绝对时段(data);
  const 期长 = 经济配置.收租周期时段;
  const 提示们: string[] = [];
  const 自然平息 = 结算风闻日变(data);
  if (自然平息 > 0) 提示们.push(`【风闻】这一整天没有新的动静，风闻自然平息 ${自然平息} 点。`);
  const 管理 = data.系统._管理考核;
  const 结算房租至 = (截止时段: number): { 应收: number; 实收: number } => {
    let 应收 = 0;
    let 实收 = 0;
    for (const [m, 节点] of Object.entries(data.户)) {
      const 配 = 户静态表[m as 门牌];
      if (!配 || !配.月租) continue;
      const 期号 = Math.floor((截止时段 - 节点._入住时段) / 期长);
      if (期号 <= 0 || 期号 <= 节点._上次收租期) continue;
      const 笔数 = 期号 - Math.max(节点._上次收租期, 0);
      节点._上次收租期 = 期号;
      const 到期额 = 配.月租 * 笔数;
      应收 += 到期额;
      if (配.天生欠租) {
        节点._欠租笔数 += 笔数;
        提示们.push(`【房租】${配.妻名}家(${m})又有 ${笔数} 笔房租没动静——累计欠租 ${节点._欠租笔数} 笔,得上门催了。`);
      } else {
        const 到账 = 到期额;
        data.现金 += 到账;
        实收 += 到账;
        提示们.push(`【房租】${m} ${配.妻名}家 ${笔数} 笔房租到账 ¥${到账}。`);
      }
    }
    return { 应收, 实收 };
  };
  const 登记本期租金 = (账: { 应收: number; 实收: number }) => {
    管理.本期新增应收 += 账.应收;
    管理.本期实收 += 账.实收;
  };

  // 睡眠或其他快进可以一次越过多个账期：按时间顺序逐期考核，不能只结最后一期。
  const 当前全局期 = Math.floor(当前绝对时段 / 期长);
  const 首个待结期 = Math.max(1, data.系统._上次上交期 + 1);
  if (首个待结期 <= 当前全局期) 惰性结算全楼(data);
  for (let 全局期 = 首个待结期; 全局期 <= 当前全局期; 全局期 += 1) {
    const 期界时段 = 全局期 * 期长;
    // 跳时前若该期尚未来得及跑普通节拍，仍要按期初时段补生成，再在本期界结算；
    // 这样跨过 N 期等价于逐期推进 N 次，而不是只在终点生成最后一期。
    const 补生任务 = 生成本期管理任务(data, 全局期 - 1, (全局期 - 1) * 期长);
    if (补生任务.length) 提示们.push(`【楼务】第${全局期 - 1}期补生 ${补生任务.length} 件任务。`);
    const 本期逾期 = 结算管理任务逾期(data, 期界时段, 全局期);
    if (本期逾期.length) 提示们.push(...本期逾期);
    // 相位错开的房租若在上个上交日之后到期，到本期考核时已经是旧账；恰在本期界到期的仍获一周期宽限。
    登记本期租金(结算房租至(期界时段 - 1));
    const 结算前欠租笔数 = Object.values(data.户).reduce((和, 节点) => 和 + Math.max(0, 节点._欠租笔数), 0);
    data.系统._上次上交期 = 全局期;
    const 报表行: string[] = [];
    const 难度 = 难度表[data.系统._难度] ?? 难度表['标准'];
    let 未接上通来电 = false;
    const 旧待接 = data.系统._待接来电;
    const 延续紧急危机 = 旧待接.期 >= 0 && 旧待接.紧急;

    // 上一通来电还挂着没接=被覆盖,失职扣分(不接爸的电话本身就是失职)
    if (旧待接.期 >= 0) {
      // 收尾竞态中产生的危机还没有可接听窗口，只排入下一通，不按“未接”追责。
      const 收尾中危机 = 延续紧急危机 && data.系统._父亲通话.状态 === '收尾中';
      if (!收尾中危机) {
        未接上通来电 = true;
        登记胜任变动(data, {
          id: `考核:${全局期}:未接来电:${旧待接.期}`,
          变动: -经济配置.未接覆盖扣分,
          类别: '失联抗命',
          原因: 延续紧急危机 ? '上通紧急危机电话一直未接' : '上通父亲电话未接',
          时段: 期界时段,
          考核期: 全局期,
        });
        报表行.push(延续紧急危机 ? '上通紧急危机电话一直未接' : '上通电话你一直没接');
      } else {
        报表行.push('通话收尾期间新增的紧急危机已排入下一通');
      }
    }

    // 动态上交只看本期新增应收；没有新增应收则不加不扣。
    const 上交 = 按百元取整(管理.本期新增应收 * 难度.上交比例);
    const 实交 = Math.min(data.现金, 上交);
    data.现金 -= 实交;
    管理.本期应上交 = 上交;
    管理.本期实际上交 = 实交;
    const 缺口 = 上交 - 实交;
    if (上交 <= 0) {
      报表行.push('本期没有新增应收，不安排上交');
    } else {
      const 完成率 = 实交 / 上交;
      const 扣分 = 上交不足扣分(完成率);
      if (扣分 === 0) {
        const 加分 = 登记胜任变动(data, {
          id: `考核:${全局期}:足额上交`,
          变动: 经济配置.足额上交加分,
          类别: '正向经营',
          原因: `本期足额上交 ¥${上交}`,
          时段: 期界时段,
          考核期: 全局期,
          数值上限: 80,
        });
        报表行.push(`本期足额上交 ¥${上交}${加分 ? `(+${加分})` : ''}`);
      } else {
        登记胜任变动(data, {
          id: `考核:${全局期}:上交缺口`,
          变动: -扣分,
          类别: '账目亏空',
          原因: `本期应交 ¥${上交}，实交 ¥${实交}`,
          时段: 期界时段,
          考核期: 全局期,
        });
        报表行.push(`本期应交 ¥${上交}，实交 ¥${实交}，完成${Math.floor(完成率 * 100)}%(-${扣分})`);
      }
    }

    // 上期欠租若到这次查账仍没处理，按笔追责；新欠租从下一期开始计入，给玩家明确处置窗口。
    if (结算前欠租笔数 > 0) {
      const 欠租扣分 = Math.min(经济配置.欠租最高扣分, 结算前欠租笔数 * 经济配置.欠租每笔扣分);
      登记胜任变动(data, {
        id: `考核:${全局期}:旧欠租`,
        变动: -欠租扣分,
        类别: '账目亏空',
        原因: `${结算前欠租笔数}笔旧欠租未处理`,
        时段: 期界时段,
        考核期: 全局期,
      });
      报表行.push(`${结算前欠租笔数}笔旧欠租未处理(-${欠租扣分})`);
    }

    // 风闻责任只在父亲周期报表里结算一次；同事件若已经按楼务逾期扣过，不再重复叠加。
    const 风闻责任 = 取待结父亲风闻责任(data, 期界时段);
    for (const 责任 of 风闻责任) {
      if (责任.扣分 > 0) {
        登记胜任变动(data, {
          id: `风闻责任:${责任.事件ID}:考核:${全局期}`,
          变动: -责任.扣分,
          类别: 风闻责任类别(data, 责任.事件ID),
          原因: 责任.摘要 || '楼内风闻责任首次传到父亲',
          时段: 期界时段,
          考核期: 全局期,
        });
      }
    }
    const 本期风闻原因 = 风闻通牒原因(data, 风闻责任, 延续紧急危机);

    const 红线 = 难度.胜任度红线;
    const 试算危险 = data.胜任度 > 红线 && data.胜任度 <= 红线 + 9;
    const 圆场记录 = 管理.母亲圆场;
    if (试算危险 && 圆场记录.危险轮次起期 < 0) 圆场记录.危险轮次起期 = 全局期;
    const 本轮未用 = 圆场记录.危险轮次起期 >= 0 && 圆场记录.上次使用期 < 圆场记录.危险轮次起期;
    let 圆场快照: SchemaType['系统']['_待接来电']['母亲圆场'] = {
      触发: false,
      事件ID: '',
      摘要: '',
      仅剧情: false,
    };
    if (试算危险 && data.系统._母亲入列 && 本轮未用) {
      const 可圆 = 风闻责任.find(责任 => 责任.可圆场 && 责任.扣分 > 0);
      if (可圆) {
        登记胜任变动(data, {
          id: `母亲圆场:${可圆.事件ID}:考核:${全局期}`,
          变动: 可圆.扣分,
          类别: 风闻责任类别(data, 可圆.事件ID),
          原因: `母亲替你解释“${可圆.摘要}”`,
          时段: 期界时段,
          考核期: 全局期,
          计入本期正向: false,
        });
        标记父亲风闻责任(data, 可圆.事件ID, '母亲已圆场');
        圆场快照 = { 触发: true, 事件ID: 可圆.事件ID, 摘要: 可圆.摘要, 仅剧情: false };
        报表行.push(`母亲已替你解释“${可圆.摘要}”，本次未计风闻责任`);
      } else {
        圆场快照 = { 触发: true, 事件ID: '', 摘要: '', 仅剧情: true };
        报表行.push('母亲替你说了话，但实账与逾期责任仍照常结算');
      }
      圆场记录.上次使用期 = 全局期;
      圆场记录.事件ID = 圆场快照.事件ID;
    }
    for (const 责任 of 风闻责任) {
      if (责任.事件ID === 圆场快照.事件ID && !圆场快照.仅剧情) continue;
      标记父亲风闻责任(data, 责任.事件ID, '已计责');
      报表行.push(
        责任.已由逾期计责
          ? `风闻投诉“${责任.摘要}”已按楼务逾期记责`
          : `风闻投诉“${责任.摘要}”首次传到父亲(-${责任.扣分})`,
      );
    }

    报表行.push(...未结楼务报表(data, 期界时段));
    报表行.push(...按期完成楼务报表(data, 期界时段, 缺口 > 0 || 结算前欠租笔数 > 0 || 未接上通来电));

    // 通牒判定(唯一真 Game Over 的传动轴)
    let 通牒 = false;
    if (data.系统._通牒期 >= 0 && 全局期 > data.系统._通牒期) {
      if (data.胜任度 <= 红线) {
        const 累计主因 = 读取胜任主因(data, data.系统._通牒期, 全局期);
        const 类别 =
          累计主因.类别 === '综合失职'
            ? 管理.通牒主因
              ? (管理.通牒主因 as 胜任责任类别)
              : 旧通牒类别(管理.通牒原因)
            : 累计主因.类别;
        const 原因 =
          累计主因.扣分 > 0
            ? 主因说明(类别, 累计主因.原因)
            : 管理.通牒原因 || '综合失职：综合胜任度低于考核红线';
        管理.通牒主因 = 类别;
        管理.通牒原因 = 原因;
        data.系统._坏结局 = 坏结局文本(类别, 原因);
        提示们.push('【考验失败】父亲回来了。');
        return 提示们;
      }
      data.系统._通牒期 = -1;
      管理.通牒主因 = '';
      管理.通牒原因 = '';
      报表行.push('上一期的账你救回来了');
    } else if (data.胜任度 <= 红线 && data.系统._通牒期 < 0) {
      data.系统._通牒期 = 全局期;
      const 本期新逾期原因 = 逾期楼务原因(data, 本期逾期.任务, 期界时段);
      const 本期主因 = 读取胜任主因(data, 全局期, 全局期);
      if (本期主因.扣分 > 0) {
        管理.通牒主因 = 本期主因.类别;
        管理.通牒原因 = 主因说明(本期主因.类别, 本期主因.原因);
      } else if (缺口 > 0 || 结算前欠租笔数 > 0) {
        管理.通牒主因 = '账目亏空';
        管理.通牒原因 = 缺口 > 0 ? `上交仍缺 ¥${缺口}` : `${结算前欠租笔数}笔旧欠租未处理`;
      } else if (本期新逾期原因 || 逾期楼务原因(data, [], 期界时段, true)) {
        管理.通牒主因 = '楼务失职';
        管理.通牒原因 = 本期新逾期原因 || 逾期楼务原因(data, [], 期界时段, true);
      } else if (本期风闻原因) {
        管理.通牒主因 = 本期风闻原因.startsWith('母亲事发') ? '母亲事发' : '公开丑闻';
        管理.通牒原因 = 本期风闻原因;
      } else if (未接上通来电) {
        管理.通牒主因 = '失联抗命';
        管理.通牒原因 = '上通父亲电话未接，形成失联责任';
      } else {
        管理.通牒主因 = '综合失职';
        管理.通牒原因 = '综合胜任度低于考核红线';
      }
      通牒 = true;
    }

    // 生成待接来电(P4 手机接听;分数段只给标签不给裸数值——AI 数据隔离)
    const 本通通牒 = 通牒 || (延续紧急危机 && 旧待接.通牒);
    const 分数段 = 延续紧急危机 && !本通通牒 ? '危险' : 胜任态度(data.胜任度, 红线, 本通通牒);
    const 本期报表 = 报表行.join(';');
    data.系统._待接来电 = {
      期: 全局期,
      分数段,
      报表: 延续紧急危机 ? 合并父亲报表(旧待接.报表, 本期报表) : 本期报表,
      通牒: 本通通牒,
      紧急: 延续紧急危机,
      母亲圆场:
        圆场快照.触发 || !延续紧急危机 ? 圆场快照 : { ...旧待接.母亲圆场 },
    };
    提示们.push(
      本通通牒
        ? '【来电】父亲的电话在响——这一通,最好接。'
        : 延续紧急危机
          ? '【来电】父亲的紧急危机电话仍在响。'
          : '【来电】父亲来电话了。',
    );

    // 必须先把本通圆场冻结进来电，再在真正恢复到不满或更好时结束危险轮次。
    if (data.胜任度 >= 红线 + 10) {
      圆场记录.危险轮次起期 = -1;
      圆场记录.事件ID = '';
    }

    // 结清上一期账后开启新经营账；恰在期界到期的租金属于下一期。
    管理.本期新增应收 = 0;
    管理.本期实收 = 0;
    管理.本期应上交 = 0;
    管理.本期实际上交 = 0;
    管理.本期正向 = 0;
    管理.本期完成摘要 = [];
    清理胜任旧账(data, 全局期);
    登记本期租金(结算房租至(期界时段));
  }

  // 当前期必须先按期初补生，再用快进终点结算逾期；顺序反过来会让刚补生的旧任务逃过截止。
  const 新任务 = 生成本期管理任务(data, 当前全局期, 当前全局期 * 期长);
  if (新任务.length) 提示们.push(`【楼务】新增 ${新任务.length} 件任务，地图瓷砖已经点亮。`);

  // 期界循环只能看到各自当时的水位；最后再结算末个期界到当前时段之间的新逾期。
  const 余段逾期 = 结算管理任务逾期(data, 当前绝对时段);
  if (余段逾期.length) 提示们.push(...余段逾期);

  // 最后一个全局期界之后、当前时段之前到期的房租也要到账；它们留到下一期才进入考核。
  登记本期租金(结算房租至(当前绝对时段));

  return 提示们;
}

// ============================================
// 催租三选(天生欠租户;硬催=钱到手关系崩/宽限=拿考验换攻略/垫上=钱你出她欠你人情)
// ============================================

export function 催租(data: SchemaType, 门牌号: 门牌, 选择: '硬催' | '宽限' | '垫上'): 经济结果 {
  const 节点 = data.户[门牌号];
  const 配 = 户静态表[门牌号];
  if (!节点 || !配) return { 提示: '这户没有账要结。' };
  if (节点._欠租笔数 <= 0) return { 提示: '她家这期的账是清的。' };
  const 欠额 = 配.月租 * 节点._欠租笔数;
  const 妻名 = 配.妻名;
  节点._欠租笔数 = 0;

  if (选择 === '硬催') {
    data.现金 += 欠额;
    节点.妻.好感值 = _.clamp(节点.妻.好感值 - 10, 0, 100);
    return {
      提示: `¥${欠额} 到手。她关门的声音很轻,轻得像在忍着什么。`,
      事件: `【催租】{{user}}把${妻名}家欠的 ¥${欠额} 房租硬生生催了出来——她凑钱的窘迫、递钱时的难堪都被他看在眼里。演出这次不体面的收款,她之后见到他会绕着走一阵子`,
      变动: true,
    };
  }
  if (选择 === '宽限') {
    登记胜任变动(data, {
      id: `催租宽限:${门牌号}:${取绝对时段(data)}`,
      变动: -3,
      类别: '账目亏空',
      原因: `${门牌号}室欠租获准宽限`,
    });
    登记脚本正增长候选(data, 门牌号, '好感值');
    节点.妻.好感值 = _.clamp(节点.妻.好感值 + 6, 0, 100);
    return {
      提示: `批条写好了:这期缓缓也行。报表上会难看一点。`,
      事件: `【宽限】{{user}}给${妻名}批了张缓交条:"这个月先缓缓,别跟别人说。"演出她接过那张纸时的神情——别人送她礼物,只有他送她喘息`,
      变动: true,
    };
  }
  // 垫上
  if (data.现金 < 欠额) {
    节点._欠租笔数 = Math.ceil(欠额 / 配.月租); // 钱不够,账退回去
    return { 提示: `想垫上这 ¥${欠额},你兜里的钱不够。` };
  }
  data.现金 -= 欠额;
  登记脚本正增长候选(data, 门牌号, '好感值');
  节点.妻.好感值 = _.clamp(节点.妻.好感值 + 8, 0, 100);
  return {
    提示: `¥${欠额} 从你口袋里出去了。账面干净,人情记下了。`,
    事件: `【垫租】${妻名}家的欠租被{{user}}悄悄垫上了,账本上什么都看不出来。她后来知道了这件事——演出她的五味杂陈:这个人情,她不知道该怎么还`,
    变动: true,
  };
}

// ============================================
// L4 要钱按钮(钱的流向反转=堕落可视化;榨取自带刹车)
// ============================================

export function 要钱(data: SchemaType, 门牌号: 门牌, _消息楼层?: number): 经济结果 {
  const 节点 = data.户[门牌号];
  const 配 = 户静态表[门牌号];
  if (!节点 || !配) return { 提示: '要不了。' };
  if (节点.妻.当前阶段 < 4) return { 提示: '你们的关系还没到伸手的地步。' };
  const 现钟 = 取绝对时段(data);
  const 上次原 = 节点.妻._上次要钱楼层;
  // -1 表示从未要过钱；未来绝对时段戳则是回档遗留，两者都不应制造假冷却。
  const 上次 = 上次原 < 0 || 上次原 > 现钟 ? -999 : 上次原;
  if (现钟 - 上次 < 经济配置.要钱冷却时段) return { 提示: '刚开过口,再等等——吃相别太难看。' };

  节点.妻._上次要钱楼层 = 现钟;
  节点.妻._要钱次数 += 1;
  data.现金 += 经济配置.要钱数额;

  // 刹车:累计≥N次,她自己的钱见底,只能向丈夫开口——丈夫心底觉得异样
  if (节点.妻._要钱次数 >= 经济配置.要钱触发疑心次数) {
    if (!疑心冻结中(节点.夫, 现钟)) {
      节点.夫.疑心值 = _.clamp(节点.夫.疑心值 + 经济配置.要钱疑心增量, 0, 100);
    }
    return {
      提示: `¥${经济配置.要钱数额} 到手。她的私房钱早就见底了——这笔,是她跟丈夫开口要来的。`,
      事件: `【要钱】${配.妻名}又给了{{user}}一笔钱(¥${经济配置.要钱数额})。她自己的钱早花空了,这笔是她找丈夫要的——演出她跟丈夫开口的那一小段(借口、丈夫多看她的那一眼),以及她把钱递给{{user}}时不敢看他的手`,
      变动: true,
    };
  }
  return {
    提示: `她把钱塞过来,像怕你反悔似的。+¥${经济配置.要钱数额}`,
    事件: `【要钱】{{user}}向${配.妻名}开了口,她几乎没犹豫就把钱给了他(¥${经济配置.要钱数额})。演出这次给予——从他花钱开发她,到她倒贴他,钱的流向早就说明了一切`,
    变动: true,
  };
}

// ============================================
// 公共区金币(路过的小惊喜,不是可挂机副业:按绝对时段挂种子,每K时段重掷)
// ============================================

const 金币房间: readonly string[] = ['大堂', '天台', '楼梯间'];

/** 此刻该房间有没有能捡的钱(UI 与脚本共用同一真值:纯种子+chat标记) */
export function 查金币(房间id: string, 绝对时段: number): number {
  if (!金币房间.includes(房间id)) return 0;
  const 期 = Math.floor(绝对时段 / 经济配置.金币刷新时段);
  if (seededRandom(期, 房间id, '金币') >= 经济配置.金币概率) return 0;
  if (读计数().拾取[`${房间id}:${期}`]) return 0;
  const 幅 = 经济配置.金币上限 - 经济配置.金币下限;
  return 经济配置.金币下限 + Math.floor(seededRandom(期, 房间id, '金币额') * (幅 + 1));
}

export function 捡金币(data: SchemaType, 房间id: string, _消息楼层?: number): 经济结果 {
  const 现钟 = 取绝对时段(data);
  const 数额 = 查金币(房间id, 现钟);
  if (!数额) return { 提示: '地上什么都没有。' };
  const c = 读计数();
  c.拾取[`${房间id}:${Math.floor(现钟 / 经济配置.金币刷新时段)}`] = true;
  写计数(c);
  data.现金 += 数额;
  return { 提示: `【拾获】${查房间名(房间id)}角落里捡到 ¥${数额}——谁掉的零钱,进了管理员的口袋。`, 变动: true };
}

function 查房间名(id: string): string {
  return ({ 大堂: '大堂', 天台: '天台', 楼梯间: '楼梯间' } as Record<string, string>)[id] ?? id;
}

// ============================================
// 空房偷窃(破门进外出住户家翻现金;概率低数额大,事后察觉几率=疑心+/风闻+)
// ============================================

export function 空房偷窃(data: SchemaType, 门牌号: 门牌, 楼层: number): 经济结果 {
  const 节点 = data.户[门牌号];
  const 配 = 户静态表[门牌号];
  if (!节点 || !配) return { 提示: '这屋没什么可翻的。' };
  const { 房间id, 破门, 非法进入, 进房末楼 } = 读场景();
  if (房间id !== 门牌号 || !(非法进入 || 破门)) return { 提示: '得先进得去,才翻得着。' };
  const 现钟 = 取绝对时段(data);
  // 真实消息楼只校验场景连续性；住客此刻是否在家读取当前绝对时段。
  if (进房末楼 != null && 进房末楼 > 楼层) return { 提示: '这段进房记录已经失效。' };
  if (妻位置推算(门牌号, 现钟, 节点) === 门牌号 || 丈夫在楼(节点, 门牌号, 现钟) !== '外出') {
    return { 提示: '屋里有人,你的手缩了回来。' };
  }
  const c = 读计数();
  const 上次原 = c.偷窃上次[门牌号] ?? -999;
  const 上次 = 上次原 > 现钟 ? -999 : 上次原;
  if (现钟 - 上次 < 经济配置.偷窃同户冷却时段) return { 提示: '这家你翻过不久——明面上的钱不会自己长回来。' };
  c.偷窃上次[门牌号] = 现钟;
  写计数(c);

  if (seededRandom(现钟, 门牌号, '偷窃') >= 经济配置.偷窃现金概率) {
    return { 提示: '抽屉、床头、外套口袋……都翻了,没找到明面上的现金。' };
  }
  const 幅 = 经济配置.偷窃上限 - 经济配置.偷窃下限;
  const 数额 = 经济配置.偷窃下限 + Math.floor(seededRandom(现钟, 门牌号, '偷窃额') * (幅 + 1));
  data.现金 += 数额;

  // 事后察觉(支柱0:每件脏事汇入同一池子)
  if (seededRandom(现钟, 门牌号, '偷窃察觉') < 经济配置.偷窃察觉概率) {
    if (!疑心冻结中(节点.夫, 现钟)) {
      节点.夫.疑心值 = _.clamp(节点.夫.疑心值 + 经济配置.偷窃察觉疑心, 0, 100);
    }
    登记风闻事件(data, {
      id: `偷窃察觉:${现钟}:${门牌号}`,
      类型: '偷窃察觉',
      目标增量: 经济配置.偷窃察觉风闻,
      门牌: 门牌号,
      地点: 门牌号,
      摘要: `${门牌号}住户发现家中失窃痕迹`,
      迹象: '硬证据',
      投诉: '严重',
    });
    return {
      提示: `【偷窃】翻出 ¥${数额}。塞回口袋时,你听见楼道里有脚步声——不知道有没有人留意到你从这户出来。`,
      事件: `【失窃的家】${配.妻名}家最近丢了钱。她自己念叨"是不是我记错了",她丈夫没说话,但心里起了一笔账。这件事没人指向{{user}},但楼里的空气变了一点`,
      变动: true,
    };
  }
  return { 提示: `【偷窃】抽屉深处翻出 ¥${数额}。你把一切原样放好,没人会知道。`, 变动: true };
}

// ============================================
// 运作道具(机制不可见的道具版:效果脚本静默执行,AI 只看到剧情皮)
// ============================================

export function 使用运作(data: SchemaType, 道具id: string, 门牌号: 门牌 | null, 楼层: number): 经济结果 {
  const 配 = 查道具(道具id);
  if (!配 || 配.类别 !== '运作') return { 提示: '这不是能这么用的东西。' };
  const i = data.背包.indexOf(道具id);
  if (i < 0) return { 提示: '背包里没有这件东西。' };
  const 现钟 = 取绝对时段(data);

  // 需要指定户的四件
  const 户向 = ['钓鱼团购券', '夜班内推', '外地项目介绍', '代订惊喜'].includes(道具id);
  const 节点 = 户向 && 门牌号 ? data.户[门牌号] : null;
  const 户配 = 户向 && 门牌号 ? 户静态表[门牌号] : null;
  if (户向 && (!节点 || !户配 || !户配.夫名)) return { 提示: '这份"心意"得有个明确的去处。' };

  const 用掉 = () => data.背包.splice(i, 1);

  switch (道具id) {
    case '钓鱼团购券': {
      用掉();
      节点!.夫._疑心冻结至 = 现钟 + 经济配置.钓鱼冻结时段;
      return {
        提示: `${户配!.夫名}收下了券,周末的日程定了。`,
        事件: `【钓鱼】{{user}}把一张能在郊区鱼塘钓上大半天的团购券送给了${户配!.夫名}("中奖送的,放着浪费")。他高兴地收下,满脑子都是周末的鱼塘——这阵子他顾不上琢磨别的`,
        变动: true,
      };
    }
    case '夜班内推': {
      if (当前时段(现钟) !== '晚上') return { 提示: '夜班只能在晚上开工，到晚上再把这份内推交给他。' };
      用掉();
      节点!.夫._外出至 = Math.max(节点!.夫._外出至, 现钟 + 经济配置.夜班外出时段);
      return {
        提示: `${户配!.夫名}接了夜班的活。晚上的楼道,清净了。`,
        事件: `【夜班】经{{user}}介绍,${户配!.夫名}接了一段双倍工资的夜班。他为多出来的收入高兴,${户配!.妻名}晚上一个人在家的日子开始了`,
        变动: true,
      };
    }
    case '外地项目介绍': {
      const 上次原 = 节点!.夫._上次出差楼;
      // -1 表示从未使用，不能被当成“刚出差回来”；未来记录则是回档遗留，同样作废。
      const 上次 = 上次原 < 0 || 上次原 > 现钟 ? -999 : 上次原;
      if (现钟 - 上次 < 经济配置.出差每户冷却时段) return { 提示: '他刚回来没多久,再撮合一次出差太扎眼了。' };
      用掉();
      节点!.夫._上次出差楼 = 现钟;
      节点!.夫._外出至 = Math.max(节点!.夫._外出至, 现钟 + 经济配置.出差外出时段);
      return {
        提示: `行李箱轮子的声音,是这栋楼里最好听的声音。${户配!.夫名}出差去了。`,
        事件: `【出差】${户配!.夫名}接了{{user}}牵线的外地项目,一去要好一阵子。${户配!.妻名}在门口送他,挥手的弧度很标准`,
        变动: true,
      };
    }
    case '代订惊喜': {
      用掉();
      节点!.夫.疑心值 = _.clamp(节点!.夫.疑心值 - 经济配置.代订疑心直降, 0, 100);
      return {
        提示: `以她的名义订的小惊喜送到了${户配!.夫名}手上。他今天看谁都顺眼。`,
        事件: `【惊喜】${户配!.夫名}收到了一份"妻子订的"小惊喜,一整天心情都很好,看${户配!.妻名}的眼神都软了几分。没人知道下单的人是谁`,
        变动: true,
      };
    }
    case '全楼聚餐': {
      const 冷却 = 聚餐可降低风闻(data);
      if (!冷却.可用) return { 提示: `全楼聚餐刚办过，至少还要等 ${冷却.尚余时段} 个时段。` };
      if (data.风闻 <= 风闻最低值(data)) return { 提示: '当前没有还能通过聚餐平息的风闻。' };
      用掉();
      const 降低 = 使用聚餐降低风闻(data);
      return {
        提示: `大排档两桌,酒过三巡。一顿饭下去,楼里的闲话淡了。风闻 -${降低}。`,
        事件: '【聚餐】物业做东,全楼在楼下大排档吃了一顿。烟火气一上来,那些阳台对望的眼神和走廊里的窃语都被冲淡了不少',
        变动: true,
      };
    }
    case '粉刷翻新': {
      const 绝对时段 = 取绝对时段(data);
      const 当前期 = Math.floor(绝对时段 / 经济配置.收租周期时段);
      if (data.系统._管理考核.粉刷冷却至期 >= 0 && 当前期 < data.系统._管理考核.粉刷冷却至期) {
        return { 提示: `本轮粉刷维护仍在冷却，要到第 ${data.系统._管理考核.粉刷冷却至期} 期才能再次安排。` };
      }
      const 公共维护 = 结算粉刷公共维护任务(data);
      if (公共维护.命中) {
        用掉();
        data.系统._管理考核.粉刷冷却至期 = 当前期 + 3;
        return {
          提示: `${公共维护.提示}三期内不再重复安排整楼粉刷。`,
          事件: '【翻新】楼道重新粉刷,扶手除了锈。原本挂在任务板上的公共维护也一并验收完成',
          变动: true,
        };
      }
      if (data.胜任度 >= 100 || data.系统._管理考核.本期正向 >= 6) {
        return { 提示: '当前胜任和本期正向额度都已没有提升空间，粉刷材料没有被消耗。' };
      }
      用掉();
      const 加分 = 登记胜任变动(data, {
        id: `主动粉刷:${当前期}`,
        变动: 3,
        类别: '正向经营',
        原因: '主动完成楼道粉刷翻新',
        时段: 绝对时段,
        考核期: 当前期 + 1,
      });
      data.系统._管理考核.粉刷冷却至期 = 当前期 + 3;
      return {
        提示: `楼道焕然一新。这笔支出,账目上很漂亮。${加分 ? `胜任度 +${加分}。` : ''}三期内不再重复安排整楼粉刷。`,
        事件: '【翻新】楼道重新粉刷,扶手除了锈。住户们进出都要摸一把新墙,交口称赞管理员会办事',
        变动: true,
      };
    }
    case '节日礼盒全员装': {
      用掉();
      for (const 节 of Object.values(data.户)) 节.妻.上次互动楼层 = 楼层;
      return {
        提示: '每户门口挂上了小礼盒。全楼太太们都记起了你的好。',
        事件: '【礼盒】每户门把手上都挂了一份管理处的节日小礼盒。这栋楼的太太们提起管理员,语气都热了几分',
        变动: true,
      };
    }
    case '物业巡检表': {
      用掉();
      const 行 = Object.keys(data.户)
        // 存在性守卫(审计 低危13):`!undefined?.隐身` 为 true,野门牌会放行到下面的裸取炸掉
        .filter(m => 户静态表[m as 门牌] && !户静态表[m as 门牌].隐身)
        .map(m => {
          const 配2 = 户静态表[m as 门牌];
          const 妻在 = 妻位置推算(m as 门牌, 现钟, data.户[m as 门牌]) === m ? '在家' : '不在';
          const 夫在 = 配2.夫名 ? 丈夫在楼(data.户[m as 门牌], m as 门牌, 现钟) : '—';
          return `${m}:${配2.妻名}${妻在}/${配2.夫名 || '—'}${夫在}`;
        })
        .join(' | ');
      return { 提示: `【巡检】${行}`, 变动: true };
    }
    default:
      return { 提示: '这件东西还没想好怎么用。' };
  }
}

// ============================================
// 父亲来电(P3 生成状态,P4 手机接听;这里只负责接听/挂断的账)
// ============================================

export function 空父亲通话(): SchemaType['系统']['_父亲通话'] {
  return {
    标识: '',
    状态: '',
    期: -1,
    分数段: '',
    报表: '',
    通牒: false,
    紧急: false,
    母亲圆场: { 触发: false, 事件ID: '', 摘要: '', 仅剧情: false },
    主题: '',
    记录: [],
    待回复: { 序号: 0, 玩家说: '' },
    下次回复序号: 1,
    挂断楼层: -1,
  };
}

export interface 接听来电结果 {
  成功: boolean;
  标识: string;
}

/**
 * 把“尚未接听”原子转成“通话中”。胜任度态度分与两个状态的交接由调用方在同一次
 * `脚本写入` 中落库，刷新绝不会再落入“待接已清、通话尚未建立”的空窗。
 */
export function 接听来电(data: SchemaType, 通话标识: string): 接听来电结果 {
  const 进行中 = data.系统._父亲通话;
  if (进行中.标识 && 进行中.期 >= 0) return { 成功: false, 标识: 进行中.标识 };
  const 电 = data.系统._待接来电;
  if (电.期 < 0 || !通话标识) return { 成功: false, 标识: '' };
  登记胜任变动(data, {
    id: `接听父亲来电:${电.期}:${通话标识}`,
    变动: 经济配置.接听来电加分,
    类别: '正向经营',
    原因: `按时接听第${电.期}期父亲来电`,
    数值上限: 80,
  });
  data.系统._父亲通话 = {
    ...空父亲通话(),
    标识: 通话标识,
    状态: '通话中',
    期: 电.期,
    分数段: 电.分数段,
    报表: 电.报表,
    通牒: 电.通牒,
    紧急: 电.紧急,
    母亲圆场: { ...电.母亲圆场 },
    待回复: { 序号: 1, 玩家说: '(通话接通,父亲先开口)' },
    下次回复序号: 2,
  };
  data.系统._待接来电 = {
    期: -1,
    分数段: '',
    报表: '',
    通牒: false,
    紧急: false,
    母亲圆场: { 触发: false, 事件ID: '', 摘要: '', 仅剧情: false },
  };
  return { 成功: true, 标识: 通话标识 };
}

export function 挂断来电(data: SchemaType): void {
  // 挂断不清状态:红点继续挂着,下一期被覆盖时照扣(不接爸的电话本身就是失职)
  void data;
}
